62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /** Dedicated audit logger; emits one line per successful owner create. */
70	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        // Normalize the address up front so every downstream use (the required-field check,
119	        // household-duplicate detection, the shared household id and the stored/returned value)
120	        // works from the same canonical form.
121	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
122	        List<String> missingFields = new ArrayList<>();
123	        if (isBlank(ownerFieldsDto.getFirstName())) {
124	            missingFields.add("firstName");
125	        }
126	        if (isBlank(ownerFieldsDto.getLastName())) {
127	            missingFields.add("lastName");
128	        }
129	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
130	        if (isBlank(normalizedAddress)) {
131	            missingFields.add("address");
132	        }
133	        if (isBlank(ownerFieldsDto.getCity())) {
134	            missingFields.add("city");
135	        }
136	        if (isBlank(ownerFieldsDto.getTelephone())) {
137	            missingFields.add("telephone");
138	        }
139	        if (!missingFields.isEmpty()) {
140	            throw new InvalidOwnerFieldsException(missingFields);
141	        }
142	        // Determine the effective registration date up front so every downstream use (the daily
143	        // create-limit, the stored value and anything derived from it such as the membership number's
144	        // year segment) works from the same business-day-adjusted date. The effective date is the
145	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
146	        // forward to the following Monday.
147	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
148	            ? ownerFieldsDto.getRegistrationDate()
149	            : LocalDate.now();
150	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
151	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
152	        // already carry this adjusted business day's registration date, no further owners may be
153	        // created for that day.
154	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
155	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
156	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
157	        }
158	        // Flag a bulk signup once more than 80 owners have already been created for this
159	        // business day, sharing the same daily accumulation path as the create-limit rule above.
160	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
161	        // Reject the request when the owner's city is already full: a city that already holds the
162	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
163	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
164	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
165	        }
166	        // Postcode is optional; when present it must be a 4-digit value that is valid for the
167	        // owner's city per the fixed region ranges. A malformed or out-of-range postcode is
168	        // rejected with a 400. An absent postcode leaves the request contract unchanged.
169	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
170	        // Normalize the telephone into E.164 form; a number that cannot form a valid
171	        // E.164 value is rejected with a 400.
172	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
173	        // Email is optional; when present it must be a syntactically valid address and is
174	        // stored lower-cased. An invalid address is rejected with a 400.
175	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
176	        // Derive the household id up front (a deterministic function of the normalized last name and
177	        // address) whenever the caller opts into a shared household, so it can feed the identity key
178	        // below. Owners not admitted into a household have a null household id.
179	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
180	        String householdId = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
181	            ? householdId(normalizedLastName, normalizedAddress)
182	            : null;
183	        // All duplicate detection is consolidated into a single derived identity key:
184	        // 'normalizedTelephone + | + (email or empty) + | + householdId'. Because the telephone is
185	        // part of the key, two members of the same household (same householdId) with different
186	        // telephones have different keys and are both allowed; only an exact whole-key match is a
187	        // duplicate. Reject with 409 when a new owner's whole identity key equals an existing one's.
188	        String identityKey = identityKey(normalizedTelephone, normalizedEmail, householdId);
189	        boolean identityInUse = this.clinicService.findAllOwners().stream()
190	            .anyMatch(existing -> identityKey.equals(
191	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
192	        if (identityInUse) {
193	            throw new DuplicateOwnerIdentityException(identityKey);
194	        }
195	        // For a shared household, backfill the shared identifier onto any existing member of this
196	        // household so the whole household carries the same stable value.
197	        if (householdId != null) {
198	            for (Owner existing : this.clinicService.findAllOwners()) {
199	                if (collapse(existing.getLastName()).equals(normalizedLastName)
200	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress)
201	                    && !householdId.equals(existing.getHouseholdId())) {
202	                    existing.setHouseholdId(householdId);
203	                    this.clinicService.saveOwner(existing);
204	                }
205	            }
206	        }
207	        HttpHeaders headers = new HttpHeaders();
208	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
209	        owner.setAddress(normalizedAddress);
210	        owner.setTelephone(normalizedTelephone);
211	        owner.setEmail(normalizedEmail);
212	        owner.setHouseholdId(householdId);
213	        // Record how many existing owners (before this create) share this owner's first and last
214	        // name, compared case-insensitively. Computed against the current owners so the new owner
215	        // itself is never counted.
216	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
217	        // Record the size of this owner's household (owners sharing the same householdId) after this
218	        // create: the existing members already stamped with the shared identifier plus this new
219	        // owner. An owner not admitted into any household is a household of one.
220	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
221	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
222	        owner.setBulkSignupWarning(bulkSignupWarning);
223	        // Store the business-day-adjusted effective registration date computed above. This defaults
224	        // to the server's current date when none was supplied and rolls any weekend date forward to
225	        // the following Monday, so everything derived from it (e.g. the membership number's year
226	        // segment) uses the adjusted date.
227	        owner.setRegistrationDate(effectiveRegistrationDate);
228	        // Assign the customer code: '<CITY3>-<LAST3>-<NNNN>' where CITY3 is the upper-cased first
229	        // three letters of the city, LAST3 the upper-cased first three letters of the last name and
230	        // NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number of
231	        // owners already in that city.
232	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
233	        this.clinicService.saveOwner(owner);
234	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
235	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
236	        // customer code, the effective registration date and the numeric membership level.
237	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
238	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
239	        headers.setLocation(UriComponentsBuilder.newInstance()
240	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
241	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
242	    }
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Override
246	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
